module ActionDispatch;class SSL;HSTS_EXPIRES_IN=63072000;PERMANENT_REDIRECT_REQUEST_METHODS= %w[GET HEAD]
def self.default_hsts_options;{expires:HSTS_EXPIRES_IN,subdomains:true,preload:false};end;def initialize(app,redirect:{},hsts:{},secure_cookies:true,ssl_default_redirect_status:nil)@app=app;@redirect=redirect;@exclude=@redirect&&@redirect[:exclude]||proc{!@redirect};@secure_cookies=secure_cookies;@hsts_header=build_hsts_header(normalize_hsts_options(hsts));@ssl_default_redirect_status=ssl_default_redirect_status;end;def call(env)request=Request.new env;if request.ssl?;@app.call(env).tap do |status,headers,body|set_hsts_header!headers;flag_cookies_as_secure!headers if @secure_cookies&&!@exclude.call(request);end;else return redirect_to_https request unless @exclude.call(request);@app.call(env);end;end;private;def set_hsts_header!(headers)headers[Constants::STRICT_TRANSPORT_SECURITY]||=@hsts_header;end;def normalize_hsts_options(options)case options;when false;self.class.default_hsts_options.merge(expires:0);when nil,true;self.class.default_hsts_options;else self.class.default_hsts_options.merge(options);end;end;def build_hsts_header(hsts)value=+"max-age=#{hsts[:expires].to_i}";value<<"; includeSubDomains" if hsts[:subdomains];value<<"; preload" if hsts[:preload];value;end;def flag_cookies_as_secure!(headers)cookies=headers[Rack::SET_COOKIE];return unless cookies;if Gem::Version.new(Rack::RELEASE)<Gem::Version.new("3");cookies=cookies.split("\n");headers[Rack::SET_COOKIE]=cookies.map{|cookie|if !/;\s*secure\s*(;|$)/i.match?(cookie);"#{cookie}; secure";else cookie;end}.join("\n");else headers[Rack::SET_COOKIE]=Array(cookies).map do |cookie|if !/;\s*secure\s*(;|$)/i.match?(cookie);"#{cookie}; secure";else cookie;end;end;end;end;def redirect_to_https(request)[@redirect.fetch(:status,redirection_status(request)),{Rack::CONTENT_TYPE=>"text/html; charset=utf-8",Constants::LOCATION=>https_location_for(request)},(@redirect[:body]||[])];end;def redirection_status(request)if PERMANENT_REDIRECT_REQUEST_METHODS.include?(request.raw_request_method);301
elsif @ssl_default_redirect_status;@ssl_default_redirect_status;else 307
end;end;def https_location_for(request)host=@redirect[:host]||request.host;port=@redirect[:port]||request.port;location=+"https://#{host}";location<<":#{port}" if port!=80&&port!=443;location<<request.fullpath;location;end;end;end
